#include <stdio.h>
#include <assert.h>
#include <math.h>
#include <complex.h>

/* 辅助：判断两个 double 近似相等 */
static int dbl_eq(double a, double b, double eps)
{
    return fabs(a - b) <= eps;
}

int main(void)
{
