     * 通过赋值给正确类型的变量来静态检查返回类型。 */
    double complex        z  = 1.0 + 2.0 * I;
    float  complex        zf = 1.0f + 2.0f * I;
    long double complex   zl = 1.0L + 2.0L * I;

