    assert(dbl_eq((double)crealf(rf), cos(1.0) * cosh(2.0)));
    assert(dbl_eq((double)cimagf(rf), -sin(1.0) * sinh(2.0)));
    assert(dbl_eq((double)creall(rl), cos(1.0L) * cosh(2.0L)));
    assert(dbl_eq((double)cimagl(rl), -sin(1.0L) * sinh(2.0L)));

