        assert(creal(r) >= 0.0);
        /* 结果应为 0 + 2i 或 0 - 2i 之一，但按右半平面约定实部为 0 */
        assert(close_enough(creal(r), 0.0, 1e-12));
        assert(close_enough(fabs(cimag(r)), 2.0, 1e-12));
