    assert(isblank('\t') != 0);
    assert(isblank('\n') == 0);  /* 换行不是 blank -> 假 */
    assert(isblank('a') == 0);

    /* ---- iscntrl：控制字符 ---- */
    assert(iscntrl('\n') != 0);
    assert(iscntrl('\t') != 0);
    assert(iscntrl('\0') != 0);
    assert(iscntrl('a') == 0);   /* 可打印字符不是控制字符 -> 假 */
    assert(iscntrl(' ') == 0);

    /* ---- isdigit：十进制数字 ---- */
    assert(isdigit('0') != 0);
    assert(isdigit('5') != 0);
    assert(isdigit('9') != 0);
    assert(isdigit('a') == 0);   /* 字母不是数字 -> 假 */
    assert(isdigit(' ') == 0);

    /* ---- isgraph：有图形表示的字符（可打印且非空格） ---- */
    assert(isgraph('a') != 0);
    assert(isgraph('!') != 0);
    assert(isgraph(' ') == 0);   /* 空格无图形表示 -> 假 */
    assert(isgraph('\n') == 0);

    /* ---- islower：小写字母 ---- */
    assert(islower('a') != 0);
    assert(islower('z') != 0);
    assert(islower('A') == 0);   /* 大写不是小写 -> 假 */
    assert(islower('0') == 0);

    /* ---- isprint：可打印字符（含空格） ---- */
    assert(isprint('a') != 0);
    assert(isprint(' ') != 0);   /* 空格可打印 -> 真 */
    assert(isprint('\n') == 0);  /* 换行不可打印 -> 假 */
    assert(isprint('\0') == 0);

    /* ---- ispunct：标点符号 ---- */
    assert(ispunct('!') != 0);
    assert(ispunct('.') != 0);
    assert(ispunct(',') != 0);
    assert(ispunct('a') == 0);   /* 字母不是标点 -> 假 */
    assert(ispunct(' ') == 0);

    /* ---- isspace：空白字符 ---- */
    assert(isspace(' ') != 0);
    assert(isspace('\t') != 0);
    assert(isspace('\n') != 0);
    assert(isspace('\v') != 0);
    assert(isspace('\f') != 0);
    assert(isspace('\r') != 0);
    assert(isspace('a') == 0);   /* 字母不是空白 -> 假 */

    /* ---- isupper：大写字母 ---- */
    assert(isupper('A') != 0);
    assert(isupper('Z') != 0);
    assert(isupper('a') == 0);   /* 小写不是大写 -> 假 */
    assert(isupper('0') == 0);

    /* ---- isxdigit：十六进制数字 ---- */
    assert(isxdigit('0') != 0);
    assert(isxdigit('9') != 0);
    assert(isxdigit('a') != 0);
    assert(isxdigit('F') != 0);
    assert(isxdigit('g') == 0);  /* 'g' 不是十六进制数字 -> 假 */
    assert(isxdigit(' ') == 0);

    /* [1] “当且仅当”的互斥性检查：
     * 一个字符不可能同时是 digit 和 alpha（对 ASCII 字母数字集合）。 */
    assert(!(isdigit('a') != 0 && isalpha('a') != 0));
    assert(!(isdigit('5') != 0 && isalpha('5') != 0));

    /* [1] 返回值语义：标准只保证“非零表示真、零表示假”，
     * 因此用 != 0 / == 0 判断，而非假定返回 1 / 0。 */
    {
        int r = isalpha('A');
        assert(r != 0);          /* 真值：非零即可 */
        r = isalpha('1');
        assert(r == 0);          /* 假值：必须为 0 */
    }

    printf("C99 7.4.1 character classification: all positive tests passed.\n");
