    assert(isalnum('a') != 0);
    assert(isalnum('z') != 0);
    assert(isalnum('A') != 0);
    assert(isalnum('Z') != 0);

    /* 数字：isalnum 为真 */
    assert(isalnum('0') != 0);
    assert(isalnum('5') != 0);
    assert(isalnum('9') != 0);

    /* 既非字母也非数字：isalnum 为假 */
    assert(isalnum(' ') == 0);
    assert(isalnum('\t') == 0);
    assert(isalnum('\n') == 0);
    assert(isalnum('!') == 0);
    assert(isalnum('@') == 0);
    assert(isalnum('[') == 0);
    assert(isalnum('~') == 0);
    assert(isalnum('\0') == 0);
}

/* [1] 参数类型为 int，可接受 EOF 与 unsigned char 值 */
static void test_int_argument(void)
{
    assert(fp_isalnum == isalnum);   /* 函数指针签名匹配 */
    assert(fp_isalnum('a') != 0);
    assert(fp_isalnum('7') != 0);
    assert(fp_isalnum(' ') == 0);
    assert(fp_isalnum(EOF) == 0);
}

int main(void)
{
    test_equivalence();
    test_specific_chars();
    test_int_argument();

    printf("C99 7.4.1.1 isalnum: all positive tests passed.\n");
    return 0;
}

