/* [5] 异常宏：若定义，则展开为整型常量表达式；
 *     任意组合的按位 OR 结果互不相同；
 *     任意组合的按位 AND 结果为 0（即各宏是互不重叠的位）。
 *     这里对实现实际定义的宏逐一检查。
 */
static void test_exception_macros(void)
{
    /* 收集实现定义的异常宏 */
    int macros[8];
    int n = 0;

#ifdef FE_DIVBYZERO
    macros[n++] = FE_DIVBYZERO;
#endif
#ifdef FE_INEXACT
    macros[n++] = FE_INEXACT;
#endif
#ifdef FE_INVALID
    macros[n++] = FE_INVALID;
#endif
#ifdef FE_OVERFLOW
    macros[n++] = FE_OVERFLOW;
#endif
#ifdef FE_UNDERFLOW
    macros[n++] = FE_UNDERFLOW;
#endif

    /* 每个宏都是整型常量表达式（能用于数组维度即证明是常量表达式） */
    {
        char const_expr_check[FE_ALL_EXCEPT >= 0 ? 1 : 1];
        (void)const_expr_check;
    }

    /* 任意两个不同宏的按位 AND 必须为 0（互不重叠） */
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            assert((macros[i] & macros[j]) == 0);
        }
    }

    /* 任意组合的按位 OR 结果互不相同：检查所有非空子集的 OR 值唯一 */
    {
        int ors[256];
        int cnt = 0;
        int total = 1 << n;
        for (int mask = 1; mask < total; mask++) {
            int v = 0;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) v |= macros[i];
            }
            /* 与之前所有 OR 值比较，必须互不相同 */
            for (int k = 0; k < cnt; k++) {
                assert(ors[k] != v);
            }
            ors[cnt++] = v;
        }
    }
}

