        int excepts = 0;

#ifdef FE_DIVBYZERO
        excepts |= FE_DIVBYZERO;
#endif
#ifdef FE_INEXACT
        excepts |= FE_INEXACT;
#endif
#ifdef FE_INVALID
        excepts |= FE_INVALID;
#endif
#ifdef FE_OVERFLOW
        excepts |= FE_OVERFLOW;
#endif
#ifdef FE_UNDERFLOW
        excepts |= FE_UNDERFLOW;
#endif

