#ifdef FE_INVALID
        excepts |= FE_INVALID;
#endif
#ifdef FE_OVERFLOW
        excepts |= FE_OVERFLOW;
#endif

        if (excepts != 0) {
            feclearexcept(FE_ALL_EXCEPT);
            int rg = fegetexceptflag(&saved, excepts);
            assert(rg == 0);

            feclearexcept(FE_ALL_EXCEPT);
            int rs = fesetexceptflag(&saved, excepts);
            assert(rs == 0);

            /* 由于 saved 是在清空后取得的，写回后标志应仍为“未置位”。
