#include <stdio.h>
#include <assert.h>
#include <fenv.h>

/* 若编译器未定义 FE_ALL_EXCEPT / FE_TONEAREST 等宏，则视为不符合 7.6 */
#ifndef FE_ALL_EXCEPT
#error "C99 7.6: <fenv.h> 必须定义 FE_ALL_EXCEPT"
