        assert(fetestexcept(FE_DIVBYZERO) != 0);  /* 标志已恢复 */

        /* 清理 */
        r = feclearexcept(FE_ALL_EXCEPT);
        assert(r == 0);
    }

    /* [2] 恢复默认环境后，环境应处于默认状态（标志清零） */
