        strncpy(saved_copy, saved, sizeof saved_copy - 1);
        saved_copy[sizeof saved_copy - 1] = '\0';

        /* 改变 locale（仍用 "C"，但演示恢复流程） */
        char *r1 = setlocale(LC_ALL, "C");
        assert(r1 != NULL);

        /* [8] 用保存的字符串恢复该部分 locale */
        char *r2 = setlocale(LC_ALL, saved_copy);
        assert(r2 != NULL);
