            char *after = setlocale(LC_ALL, NULL);
            assert(after != NULL);
            assert(strcmp(after, before_copy) == 0);
        } else {
            /* 成功：返回非 NULL */
            assert(r != NULL);
        }
        /* 恢复为 "C" 以便后续测试稳定 */
        assert(setlocale(LC_ALL, "C") != NULL);
    }

    /* [6] 无法满足的选择：传入一个几乎肯定无效的 locale 名，
