    double ovf = DBL_MAX * 2.0;             /* 溢出为 +inf（IEEE 环境） */
    assert(isinf(ovf) != 0);
    double novf = -DBL_MAX * 2.0;           /* 溢出为 -inf */
    assert(isinf(novf) != 0);

    /* 1.0 / 0.0 在 IEEE 环境下为 +inf */
    double divinf = 1.0 / 0.0;
    assert(isinf(divinf) != 0);

