    /* 返回值参与算术运算 */
    assert(ilogb(2.0) + ilogb(4.0) == 3);
}

/* [2] 结果超出 int 范围时数值未指定 —— 这是 UB/未指定行为，
 *     不做负向测试，仅说明不在此处断言。 */

int main(void)
{
    /* 抑制未使用变量警告 */
    (void)p_ilogb; (void)p_ilogbf; (void)p_ilogbl;

    test_equivalence_with_logb();
    test_known_values();
    test_zero();
    test_inf();
    test_nan();
    test_return_type();

    printf("C99 7.12.6.5 ilogb: all positive tests passed.\n");
