        if (fsub > 0.0f && fsub < FLT_MIN) {
            assert(logbf(fsub) == (float)(FLT_MIN_EXP - 2));
        }

        /* 次正规 long double */
        long double lsub = LDBL_MIN / 2.0L;
        if (lsub > 0.0L && lsub < LDBL_MIN) {
            assert(logbl(lsub) == (long double)(LDBL_MIN_EXP - 2));
        }
    }

