/* [1] Synopsis：验证三个函数原型存在且返回类型正确 */
static void test_synopsis(void)
{
    /* 通过函数指针类型检查返回类型与参数类型 */
    double      (*pf_d)(double)            = fabs;
    float       (*pf_f)(float)             = fabsf;
    long double (*pf_l)(long double)       = fabsl;

    /* 调用一次，确保链接可用 */
    assert(pf_d(-1.0) == 1.0);
    assert(pf_f(-1.0f) == 1.0f);
    assert(pf_l(-1.0L) == 1.0L);

