            assert(is_integral_value(r));     /* 结果是整数值 */
            /* 与参数同号（或为零） */
            if (xs[i] > 0.0) assert(r >= 0.0);
            if (xs[i] < 0.0) assert(r <= 0.0);
        }
    }

    /* ---------- [2][3] 特殊值：0、无穷、NaN ---------- */
    assert(trunc(0.0)  == 0.0);
    assert(trunc(-0.0) == -0.0);
    assert(isinf(trunc(INFINITY))  && trunc(INFINITY)  > 0);
    assert(isinf(trunc(-INFINITY)) && trunc(-INFINITY) < 0);
