    /* [2][3] 从 0.0 朝 1.0 方向：应得到最小正次正规数（或最小正正规数，
     * 取决于实现是否支持次正规数）。这里只验证结果 > 0 且是紧邻 0 的值。 */
    {
        double r = nextafter(0.0, 1.0);
        assert(r > 0.0);
        assert(nextafter(r, 0.0) == 0.0);   /* 反向回到 0 */
    }

    /* [2][3] 从 0.0 朝 -1.0 方向：应得到最小负值 */
    {
        double r = nextafter(0.0, -1.0);
        assert(r < 0.0);
        assert(nextafter(r, 0.0) == 0.0);
