#else
#error "INT8_MIN not defined"
#endif
#ifdef INT8_MAX
#else
#error "INT8_MAX not defined"
#endif
#ifdef UINT8_MAX
#else
#error "UINT8_MAX not defined"
#endif
#ifdef INT16_MIN
#else
#error "INT16_MIN not defined"
#endif
#ifdef INT16_MAX
#else
