    /* 取值互不相同 */
    assert(SEEK_CUR != SEEK_END);
    assert(SEEK_CUR != SEEK_SET);
    assert(SEEK_END != SEEK_SET);

    /* 适合作为 fseek 的第三个参数 */
    {
        FILE *fp = tmpfile();
        if (fp != NULL) {
            fputs("hello", fp);
            int r1 = fseek(fp, 0, SEEK_SET);
            int r2 = fseek(fp, 0, SEEK_CUR);
            int r3 = fseek(fp, 0, SEEK_END);
            (void)r1; (void)r2; (void)r3;
            fclose(fp);
        }
    }
}

