/* [3] stderr / stdin / stdout：类型为 “pointer to FILE”，
 *     分别指向标准错误、输入、输出流 */
static void test_standard_streams(void)
{
    /* 类型为 pointer to FILE：可赋给 FILE* */
    FILE *in  = stdin;
    FILE *out = stdout;
    FILE *err = stderr;
    assert(in  != NULL);
    assert(out != NULL);
    assert(err != NULL);

    /* 是表达式：可取地址，得到 FILE** */
    FILE **pin  = &stdin;
    FILE **pout = &stdout;
    FILE **perr = &stderr;
    assert(*pin  == stdin);
    assert(*pout == stdout);
    assert(*perr == stderr);

    /* 三者互不相同（分别关联不同流） */
    assert(stdin  != stdout);
    assert(stdin  != stderr);
    assert(stdout != stderr);

    /* 实际可用：向 stdout 写、从 stdin 读类型正确 */
    {
        int n = fprintf(stdout, "%s", "");   /* 写 0 个字符 */
        assert(n == 0);
        fflush(stdout);
    }
}

