/* ========== 正向测试：以下代码应能编译并运行通过 ========== */

int main(void)
{
    /* [7] 程序启动时预定义三个文本流：stdin / stdout / stderr，无需显式打开 */
    assert(stdin  != NULL);
    assert(stdout != NULL);
    assert(stderr != NULL);

    /* [7] stderr 初始不是完全缓冲的（实现定义，但标准要求“not fully buffered”） */
    /* 这里只验证流对象存在且可用，不强制具体缓冲模式 */

    /* [15] FOPEN_MAX 至少为 8，包含三个标准文本流 */
    assert(FOPEN_MAX >= 8);

