    const char *fname = "c99_7_19_3_test.tmp";
    FILE *fp = fopen(fname, "w+");
    assert(fp != NULL);

    /* [1] 写入后位置指示器随写操作推进 */
    assert(fputc('A', fp) != EOF);
    assert(fputc('B', fp) != EOF);
