        /* 第一个 int 被 va_arg 取走，剩余 "B" 与 7 交给 vfprintf */
        total = mixed_va_arg_vfprintf(f, "%s", "%d", 99, "B", 7);
        assert(total == 1 + 1);   /* "B" 1 字符 + "7" 1 字符 */
        fclose(f);
    }

