        assert(fp != NULL);
    }

    /* [2] vprintf 等价于 printf：比较两者对同一格式的输出字符数 */
    {
        int n_printf, n_vprintf;

        n_printf  = printf("printf  : %d %s %.2f\n", 42, "abc", 3.14);
        n_vprintf = forward_to_vprintf("vprintf : %d %s %.2f\n",
                                       42, "abc", 3.14);

        /* 两者格式串长度相同、实参相同，返回的字符数应相等 */
        assert(n_printf == n_vprintf);
        assert(n_printf > 0);
    }

