#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <assert.h>

/* 辅助：比较两个 double 是否近似相等 */
static int dbl_eq(double a, double b)
{
    double d = a - b;
    if (d < 0) d = -d;
    return d <= 1e-9;
}

