    unsigned char *p = (unsigned char *)realloc(NULL, n);
    assert(p != NULL);                       /* [3] 等价 malloc，应成功 */
    for (size_t i = 0; i < n; ++i)
        p[i] = (unsigned char)i;             /* 可写 */
    free(p);
    printf("[3] realloc(NULL, n) behaves like malloc(n)\n");
}

/* [4] 返回指针可能与旧指针相同（不强制，但允许）—— 只验证返回值可用 */
