    p[0] = 1; p[1] = 2; p[2] = 3; p[3] = 4;

    int *q = (int *)realloc(p, 8 * sizeof(int));
    assert(q != NULL);
    assert(q[0] == 1 && q[1] == 2 && q[2] == 3 && q[3] == 4);
    free(q);
    printf("[4] return value points to usable new object\n");
