        assert(rc != 0);
    }

    /* [6] exit 不返回：子进程 mode 6 不应打印 "BUG" 且退出码为 0 */
    {
        int rc = run_child(6);
        assert(rc == 0);
    }

    printf("All positive tests passed.\n");
    return 0;
}

