     *     用 fork 子进程验证：子进程调用 _Exit(42)，父进程应看到退出码 42。
     */
    {
        pid_t pid = fork();
        assert(pid >= 0);
        if (pid == 0) {
            /* 子进程 */
            _Exit(42);
            /* [3] _Exit 不能返回给调用者：若返回则说明实现错误 */
            _exit(99); /* 不应到达 */
        } else {
            int status = 0;
            pid_t w = waitpid(pid, &status, 0);
            assert(w == pid);
            assert(WIFEXITED(status));
            assert(WEXITSTATUS(status) == 42);
        }
    }

    /* [2] 状态确定方式与 exit 相同：验证低 8 位截断语义。
     *     传入 0x1234，宿主环境应看到 0x34（低 8 位）。
     */
    {
        pid_t pid = fork();
        assert(pid >= 0);
        if (pid == 0) {
            _Exit(0x1234);
            _exit(99);
        } else {
            int status = 0;
            pid_t w = waitpid(pid, &status, 0);
            assert(w == pid);
            assert(WIFEXITED(status));
            assert(WEXITSTATUS(status) == (0x1234 & 0xFF));
        }
    }

    /* [2] atexit 注册的函数不被调用 */
    {
        remove_markers();
        pid_t pid = fork();
        assert(pid >= 0);
        if (pid == 0) {
            /* 注册 atexit 处理器 */
            int r = atexit(atexit_handler);
            (void)r;
            /* 调用 _Exit，atexit 处理器不应被调用 */
            _Exit(0);
            _exit(99);
