            int status = 0;
            pid_t w = waitpid(pid, &status, 0);
            assert(w == pid);
            assert(WIFEXITED(status));
            assert(WEXITSTATUS(status) == 0);
            /* 关键断言：atexit 处理器未被调用 */
            assert(!marker_exists(atexit_marker));
