    i = abs(0);
    assert(i == 0);                 /* |0| == 0 */

    i = abs(42);
    assert(i == 42);                /* |42| == 42 */

    i = abs(-42);
    assert(i == 42);                /* |-42| == 42 */

    i = abs(INT_MAX);
    assert(i == INT_MAX);           /* |INT_MAX| == INT_MAX */

    /* [2][3] labs：long 版本 */
    l = labs(0L);
    assert(l == 0L);

