        /* 用户包装函数（模拟“库函数调用 mbtowc”的场景） */
        int r2 = mbtowc(&wc2, "D", 1);
        assert(r1 == r2);
        assert(wc1 == wc2);
    }

    printf("All positive tests for C99 7.20.7.2 (mbtowc) passed.\n");

