/* [3] 每个字符按 unsigned char 解释：高位字节比较 */
static void test_unsigned_char_interpretation(void)
{
    /* 0xFF 作为 unsigned char 是 255，大于 0x01 */
    unsigned char hi = 0xFF;
    unsigned char lo = 0x01;
    char a[1];
    char b[1];
    a[0] = (char)hi;
    b[0] = (char)lo;
