/* [7] EXAMPLE 中列出的宏调用应能编译并产生与显式函数一致的结果。 */
static void test_example(void)
{
    int n = 2;
    float f = 0.5f;
    double d = 0.5;
    long double ld = 0.5L;
    float complex fc = 0.5f + 0.5f * I;
