    assert(carg(n) == carg((double complex)n));
    assert(cproj(f) == cprojf((float complex)f));
    assert(creal(d) == creal((double complex)d));
    assert(cimag(ld) == cimagl(ldc));
    assert(fabs(fc) == cabsf(fc));
