    {
        time_t t0 = (time_t)1000;
        time_t t1 = (time_t)1060;
        double d = difftime(t1, t0);
        /* 返回类型为 double */
        assert(sizeof(d) == sizeof(double));
        /* 差值为 60 秒 */
        assert(d == 60.0);
    }

