    {
        time_t start = time(NULL);
        time_t end   = start + (time_t)3600; /* 人为构造 1 小时差 */
        double secs  = difftime(end, start);
        assert(secs == 3600.0);
    }

    printf("C99 7.23.2.2 difftime: all positive tests passed.\n");
