#include <assert.h>
#include <string.h>
#include <locale.h>

/* 辅助：把宽字符流内容读回为宽字符串 */
static size_t read_back(FILE *fp, wchar_t *buf, size_t n)
{
    size_t i = 0;
    int c;
    rewind(fp);
    while (i + 1 < n && (c = fgetwc(fp)) != WEOF) {
        buf[i++] = (wchar_t)c;
    }
    buf[i] = L'\0';
    return i;
}

