    assert(fp != NULL);
    {
        int n = fwprintf(fp, L"hello");
        assert(n == 5);                 /* [2] 返回写入的宽字符数 */
        read_back(fp, buf, 256);
        assert(wcscmp(buf, L"hello") == 0);
