 *       违反它们属于未定义行为（UB），编译器不强制报错，因此不作为负向测试。
 *       本文件负向测试只针对真正的约束（如参数类型、restrict 限定等可诊断项）。
 */

#include <stdio.h>
#include <wchar.h>
#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include <locale.h>

/* 辅助：把宽字符串写入临时文件，返回 FILE*（已 rewind） */
static FILE *make_wfile(const wchar_t *ws)
{
    FILE *fp = tmpfile();
    assert(fp != NULL);
    /* 用 fputws 写入宽字符 */
    if (fputws(ws, fp) == -1) {
        fclose(fp);
        return NULL;
    }
    rewind(fp);
    return fp;
}

int main(void)
{
    /* 设置 locale 以便宽字符 I/O 正常工作 */
    setlocale(LC_ALL, "");

    /* ========== 正向测试：以下代码应能编译并运行通过 ========== */

    /* [1] 原型：int fwscanf(FILE * restrict, const wchar_t * restrict, ...);
     *     验证函数存在且返回 int。 */
    {
        FILE *fp = make_wfile(L"42");
        assert(fp != NULL);
        int x = 0;
        int r = fwscanf(fp, L"%d", &x);   /* [1] 基本调用 */
        assert(r == 1);
        assert(x == 42);
        fclose(fp);
    }

    /* [2] 从 stream 读取，按 format 转换并赋值给后续参数指向的对象。
     *     多余参数被求值但忽略。 */
    {
        FILE *fp = make_wfile(L"7 8");
        assert(fp != NULL);
        int a = 0, b = 0, extra = 0;
        int r = fwscanf(fp, L"%d %d", &a, &b, &extra); /* extra 多余，被忽略 */
        assert(r == 2);
        assert(a == 7 && b == 8);
        fclose(fp);
    }

    /* [3] format 由指令组成：空白、普通宽字符、转换规格。
     *     转换规格：% [*] [宽度] [长度修饰] 转换说明符 */
    {
        FILE *fp = make_wfile(L"abc 123");
        assert(fp != NULL);
        wchar_t buf[16] = {0};
        int n = 0;
        /* 普通宽字符 'a','b','c' + 空白 + %ls + %n */
        int r = fwscanf(fp, L"abc %ls%n", buf, &n);
        assert(r == 1);
        assert(wcscmp(buf, L"123") == 0);
        assert(n > 0);
        fclose(fp);
    }

    /* [3] 赋值抑制 * ：不赋值，不增加返回计数 */
    {
        FILE *fp = make_wfile(L"99 100");
        assert(fp != NULL);
        int y = 0;
