    /* [4] 输入失败（EOF）：返回 EOF */
    {
        FILE *fp = make_wfile(L"");
        assert(fp != NULL);
        int v = 0;
        int r = fwscanf(fp, L"%d", &v);     /* 立即 EOF -> 输入失败 */
        assert(r == EOF);
        fclose(fp);
    }

    /* [2] 格式耗尽而参数多余：多余参数被求值但忽略 */
