        assert(n2 == 0);         /* 字面量 'a' 不匹配 -> 早期匹配失败 */
    }

    /* [2] 抑制赋值（*）：不计入返回值 */
    {
        const wchar_t *s = L"10 20";
        int b = 0;
        int n = swscanf(s, L"%*d %d", &b);
        assert(n == 1);          /* 抑制的项不计入 */
        assert(b == 20);
