        int n = swscanf(s, L"%d %d", &a, &b);
        assert(n == 1);
        assert(a == 5);
    }

    /* [3] 空格式串：不进行任何转换，返回 0 */
    {
        const wchar_t *s = L"anything";
        int n = swscanf(s, L"");
        assert(n == 0);
    }

    printf("All positive tests for C99 7.24.2.4 (swscanf) passed.\n");
