static FILE *make_stdin_from_wide(const char *fname, const char *content)
{
    FILE *fp = fopen(fname, "w");
    assert(fp != NULL);
    fputs(content, fp);
    fclose(fp);
    /* 将 stdin 重定向到该文件 */
    FILE *in = freopen(fname, "r", stdin);
