/* [2] 基本拷贝语义：非重叠区域，n 个宽字符被完整拷贝。 */
static void test_basic_copy(void)
{
    wchar_t src[8] = { L'a', L'b', L'c', L'd', L'e', L'f', L'g', L'h' };
    wchar_t dst[8] = { 0 };

    wchar_t *ret = wmemmove(dst, src, 8);

    /* [3] 返回值必须等于 s1（即 dst）。 */
    assert(ret == dst);

    /* [2] 内容被正确拷贝。 */
    for (size_t i = 0; i < 8; ++i) {
