    assert(buf[1] == L'B');
    assert(buf[2] == L'A');
    assert(buf[3] == L'B');
    assert(buf[4] == L'C');
    assert(buf[5] == L'D');
    assert(buf[6] == L'G');
    assert(buf[7] == L'H');
}

/* [2] 重叠区域（向前移动，dst < src）：
