/* ========== 正向测试：以下代码应能编译并运行通过 ========== */

#include <wchar.h>
#include <assert.h>
#include <stdio.h>
#include <stddef.h>

int main(void)
{
    /* [1] 头文件 <wchar.h> 提供 wcspbrk 声明，原型为：
     *     wchar_t *wcspbrk(const wchar_t *s1, const wchar_t *s2);
     * 通过取函数指针类型来静态验证原型签名。 */
    {
        wchar_t *(*fp)(const wchar_t *, const wchar_t *) = wcspbrk;
        assert(fp != NULL);
    }

    /* [2][3] 基本情形：s1 中存在 s2 的字符，返回指向 s1 中第一个匹配字符的指针 */
    {
        const wchar_t s1[] = L"hello world";
        const wchar_t s2[] = L"ow";
        wchar_t *p = wcspbrk(s1, s2);
        /* s1 中第一个属于 {'o','w'} 的字符是 'o'（下标 4） */
        assert(p != NULL);
        assert(p == s1 + 4);
        assert(*p == L'o');
    }

    /* [2][3] s2 的第一个字符即匹配：返回 s1 起始处 */
    {
        const wchar_t s1[] = L"abcdef";
        const wchar_t s2[] = L"ax";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == s1);
        assert(*p == L'a');
    }

    /* [2][3] 匹配发生在 s1 末尾（含结尾空宽字符之前的位置） */
    {
        const wchar_t s1[] = L"abcXYZ";
        const wchar_t s2[] = L"Z";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == s1 + 5);
        assert(*p == L'Z');
    }

    /* [3] s2 中没有任何字符出现在 s1 中：返回空指针 */
    {
        const wchar_t s1[] = L"hello";
        const wchar_t s2[] = L"xyz";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == NULL);
    }

    /* [3] s1 为空宽字符串：返回空指针 */
    {
        const wchar_t s1[] = L"";
        const wchar_t s2[] = L"abc";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == NULL);
    }

    /* [3] s2 为空宽字符串：s1 中无字符来自 s2，返回空指针 */
    {
        const wchar_t s1[] = L"abc";
        const wchar_t s2[] = L"";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == NULL);
    }

    /* [2] 匹配字符为宽字符（非 ASCII），验证宽字符语义 */
    {
        const wchar_t s1[] = L"\u4e2d\u6587abc"; /* 中 文 a b c */
        const wchar_t s2[] = L"b\u6587";        /* b 文 */
        wchar_t *p = wcspbrk(s1, s2);
        /* s1 中第一个属于 {'b','文'} 的字符是 '文'（下标 1） */
        assert(p != NULL);
        assert(p == s1 + 1);
        assert(*p == L'\u6587');
    }

    /* [2][3] 返回的指针可用于修改 s1（s1 为可修改数组，参数为 const 指针） */
    {
        wchar_t s1[] = L"abcdef";
        const wchar_t s2[] = L"cd";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p == s1 + 2);
        *p = L'X'; /* 通过返回指针修改 s1 */
        assert(s1[2] == L'X');
    }

    /* [2] 返回指针指向 s1 内部，可用指针差验证位置 */
    {
        const wchar_t s1[] = L"0123456789";
        const wchar_t s2[] = L"789";
        wchar_t *p = wcspbrk(s1, s2);
        assert(p != NULL);
        assert((size_t)(p - s1) == 7);
    }

    printf("All positive tests for wcspbrk passed.\n");
    return 0;
}

