    {
        wchar_t buf[4] = { L'1', L'2', L'3', L'4' };
        wchar_t *r = wmemset(buf, L'X', 0);
        assert(buf[0] == L'1');
        assert(buf[1] == L'2');
        assert(buf[2] == L'3');
        assert(buf[3] == L'4');
