 *       两种提前停止情形（无效多字节字符 / 超出 len 字节限制）；
 *       每次转换等价于 wcrtomb 调用。
 *   [3] 若 dst 非空，*src 被赋值为 NULL（因终止空宽字符停止）
 *       或最后一个已转换宽字符之后的位置；
 *       因终止空宽字符停止时，结果状态为初始转换状态。
 *   [4] 编码错误：errno = EILSEQ，返回 (size_t)(-1)；
 *       否则返回结果多字节序列的字节数（不含终止空字符）。
 *   Footnote 302：因终止空宽字符停止时，存储的字节包含
 *       在空字节之前立即到达初始移位状态所需的字节。
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <errno.h>
#include <assert.h>
#include <locale.h>

/* ========== 正向测试：以下代码应能编译并运行通过 ========== */

/* [1] 函数原型存在性检查：通过取函数地址验证签名 */
static size_t (*fp_wcsrtombs)(char * restrict,
                              const wchar_t ** restrict,
                              size_t,
                              mbstate_t * restrict) = wcsrtombs;

/* [2][3][4] 基本转换：dst 非空，转换整个宽字符串（含终止空宽字符） */
static void test_basic_conversion(void)
{
    mbstate_t st;
    const wchar_t *src;
    wchar_t wbuf[16];
    char dst[64];
    size_t n;

    memset(&st, 0, sizeof st);

    /* 构造宽字符串 "abc" */
    wbuf[0] = L'a';
    wbuf[1] = L'b';
    wbuf[2] = L'c';
    wbuf[3] = L'\0';

    src = wbuf;
    n = wcsrtombs(dst, &src, sizeof dst, &st);

    /* [4] 返回值 = 结果多字节序列字节数，不含终止空字符 */
    assert(n == 3);
    /* [2] 转换包含终止空宽字符，也被存储 */
    assert(dst[0] == 'a');
    assert(dst[1] == 'b');
    assert(dst[2] == 'c');
    assert(dst[3] == '\0');

    /* [3] 因到达终止空宽字符而停止：*src 被赋值为 NULL */
    assert(src == NULL);
    /* [3] 结果状态为初始转换状态 */
    {
        mbstate_t init;
        memset(&init, 0, sizeof init);
        assert(memcmp(&st, &init, sizeof st) == 0);
    }
}

/* [2][3] dst 非空但 len 限制导致提前停止：
 *       *src 指向最后一个已转换宽字符之后的位置 */
static void test_len_limit_stop(void)
{
    mbstate_t st;
    const wchar_t *src;
    wchar_t wbuf[16];
    char dst[64];
    size_t n;

    memset(&st, 0, sizeof st);

    wbuf[0] = L'x';
    wbuf[1] = L'y';
    wbuf[2] = L'z';
    wbuf[3] = L'\0';

    src = wbuf;
    /* 只允许 2 字节：转换 'x','y' 后，下一个 'z' 会超出 len */
    n = wcsrtombs(dst, &src, 2, &st);

    assert(n == 2);
    assert(dst[0] == 'x');
    assert(dst[1] == 'y');

    /* [3] 未到达终止空宽字符：*src 指向最后一个已转换宽字符之后 */
    assert(src == &wbuf[2]);
    assert(*src == L'z');
}

/* [2][3] dst 为 NULL：只计算所需字节数，不存储；
 *       *src 仍按规则更新 */
static void test_null_dst(void)
{
    mbstate_t st;
    const wchar_t *src;
    wchar_t wbuf[16];
    size_t n;

    memset(&st, 0, sizeof st);

    wbuf[0] = L'h';
    wbuf[1] = L'i';
    wbuf[2] = L'\0';

    src = wbuf;
    /* dst == NULL：不存储，仅返回字节数（不含终止空字符） */
    n = wcsrtombs(NULL, &src, 0, &st);

    assert(n == 2);
    /* [3] 到达终止空宽字符：*src 被赋值为 NULL */
    assert(src == NULL);
}

/* [2][4] 编码错误：宽字符不对应有效多字节字符时，
 *       errno = EILSEQ，返回 (size_t)(-1) */
static void test_encoding_error(void)
{
    mbstate_t st;
    const wchar_t *src;
    wchar_t wbuf[4];
    char dst[64];
    size_t n;

    memset(&st, 0, sizeof st);

    /* 使用一个几乎肯定无效的宽字符值。
     * 在 C locale 下，任何 > 0x7F 的宽字符通常无法转换。
     * 这里选用一个超出常见编码范围的码点。 */
    wbuf[0] = (wchar_t)0x10FFFF; /* 通常无效 */
    wbuf[1] = L'\0';

    src = wbuf;
    errno = 0;
    n = wcsrtombs(dst, &src, sizeof dst, &st);

    /* [4] 编码错误：返回 (size_t)(-1)，errno = EILSEQ */
    if (n == (size_t)(-1)) {
        assert(errno == EILSEQ);
    }
    /* 若实现恰好能转换该码点（例如 UTF-8 locale），
     * 则跳过此断言，不视为失败。 */
}

/* [2] 每次转换等价于 wcrtomb 调用：逐字符比较结果 */
static void test_equivalence_with_wcrtomb(void)
{
    mbstate_t st1, st2;
    const wchar_t *src;
    wchar_t wbuf[8];
    char dst1[64], dst2[64];
    size_t n1, n2, i;

    memset(&st1, 0, sizeof st1);
    memset(&st2, 0, sizeof st2);

    wbuf[0] = L'A';
    wbuf[1] = L'B';
    wbuf[2] = L'\0';

    src = wbuf;
    n1 = wcsrtombs(dst1, &src, sizeof dst1, &st1);

    /* 用 wcrtomb 逐字符转换，得到 dst2 */
    {
        const wchar_t *p = wbuf;
        char *q = dst2;
        size_t total = 0;
        while (*p) {
            size_t k = wcrtomb(q, *p, &st2);
            if (k == (size_t)(-1)) break;
            q += k;
            total += k;
            p++;
        }
        /* 转换终止空宽字符 */
        {
            size_t k = wcrtomb(q, L'\0', &st2);
            if (k != (size_t)(-1)) {
                q += k;
                total += k;
            }
        }
        n2 = total;
    }

    assert(n1 == n2);
    assert(memcmp(dst1, dst2, n1 + 1) == 0);
}

/* [Footnote 302] 因终止空宽字符停止时，存储的字节包含
 * 在空字节之前立即到达初始移位状态所需的字节。
 * 在无移位状态的编码（如 UTF-8 / ASCII）下，这等价于
 * 终止空字节本身；此处验证终止空字节确实被存储。 */
static void test_footnote_302(void)
{
    mbstate_t st;
    const wchar_t *src;
    wchar_t wbuf[4];
    char dst[64];
    size_t n;

    memset(&st, 0, sizeof st);

    wbuf[0] = L'Q';
    wbuf[1] = L'\0';

    src = wbuf;
    n = wcsrtombs(dst, &src, sizeof dst, &st);

    assert(n == 1);
    assert(dst[0] == 'Q');
    /* 终止空字节被存储 */
    assert(dst[1] == '\0');
    /* 结果状态为初始转换状态 */
    {
        mbstate_t init;
        memset(&init, 0, sizeof init);
        assert(memcmp(&st, &init, sizeof st) == 0);
    }
}

int main(void)
{
    /* 使用 C locale 以保证行为可预测 */
    setlocale(LC_ALL, "C");

    /* 验证函数指针已正确初始化（原型存在） */
    assert(fp_wcsrtombs == wcsrtombs);

    test_basic_conversion();
    test_len_limit_stop();
    test_null_dst();
    test_encoding_error();
    test_equivalence_with_wcrtomb();
    test_footnote_302();

    printf("All positive tests passed.\n");
    return 0;
}

