     *     在 C locale 下，字母集合即 ASCII 字母，故可做双向检查。 */
    {
        for (wint_t wc = 0; wc < 128; ++wc) {
            int a = iswalpha(wc) != 0;
            int u = iswupper(wc) != 0;
            int l = iswlower(wc) != 0;
            if (a) {
                /* 在 C locale 中，字母必为大写或小写 */
                assert(u || l);
            }
            if (u || l) {
                assert(a);
            }
        }
    }

    /* [2] 附加字母集合的排除条件：若某字符是 locale 特定字母，
     *     则 iswcntrl/iswdigit/iswpunct/iswspace 必须全为假。
     *     在 C locale 下，用 ASCII 全范围验证该蕴含关系。 */
    {
